<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_update_profile( $user_id = 0, $from_onboarding = false ) { $user_id = $user_id ?: get_current_user_id(); if ( ! sd_core_can_edit_user( $user_id ) ) { return new WP_Error( 'forbidden', __( 'You cannot edit this profile.', 'social-discovery-core' ) ); } $display = sd_core_post_text( 'display_name' ); $bio = sd_core_post_textarea( 'description' ); $website = esc_url_raw( sd_core_post_text( 'user_url' ) ); $location = sd_core_post_text( 'location' ); $data = array( 'ID' => $user_id ); if ( $display ) { $data['display_name'] = $display; } if ( isset( $_POST['description'] ) ) { $data['description'] = $bio; } if ( isset( $_POST['user_url'] ) ) { $data['user_url'] = $website; } $result = wp_update_user( $data ); if ( is_wp_error( $result ) ) { return $result; } update_user_meta( $user_id, 'sd_profile_location', $location ); sd_core_set_profile_field( $user_id, 'About Me', $bio ); sd_core_set_profile_field( $user_id, 'Location', $location ); return $result; }
function sd_core_profile_update_handler() { $user_id = sd_core_current_user_required(); if ( ! sd_core_form_nonce( 'sd_profile_update' ) || ! sd_core_can_edit_user( $user_id ) ) { wp_die( esc_html__( 'This request could not be verified.', 'social-discovery-core' ), 403 ); } $result = sd_core_update_profile( $user_id ); if ( is_wp_error( $result ) ) { wp_safe_redirect( add_query_arg( 'sd_profile', 'error', sd_core_page_url( 'account-settings', '/' ) ) ); exit; } wp_safe_redirect( add_query_arg( 'sd_profile', 'saved', sd_core_page_url( 'account-settings', '/' ) ) ); exit; }
add_action( 'admin_post_sd_update_profile', 'sd_core_profile_update_handler' );
function sd_core_password_update_handler() { $user_id = sd_core_current_user_required(); if ( ! sd_core_form_nonce( 'sd_account_password' ) || ! sd_core_can_edit_user( $user_id ) ) { wp_die( esc_html__( 'This request could not be verified.', 'social-discovery-core' ), 403 ); } $pass1 = isset( $_POST['pass1'] ) ? (string) wp_unslash( $_POST['pass1'] ) : ''; $pass2 = isset( $_POST['pass2'] ) ? (string) wp_unslash( $_POST['pass2'] ) : ''; if ( strlen( $pass1 ) < 8 || ! hash_equals( $pass1, $pass2 ) ) { wp_safe_redirect( add_query_arg( 'sd_profile', 'password-error', sd_core_page_url( 'account-settings', '/' ) ) ); exit; } wp_set_password( $pass1, $user_id ); wp_set_auth_cookie( $user_id, false, is_ssl() ); wp_safe_redirect( add_query_arg( 'sd_profile', 'password-saved', sd_core_page_url( 'account-settings', '/' ) ) ); exit; }
add_action( 'admin_post_sd_update_password', 'sd_core_password_update_handler' );
